<script setup lang="ts">
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue';import {useI18n} from 'vue-i18n';import {useNewsroom,type NewsIndexItem} from '../api/newsroom';import {assetUrl,apiUrl} from '../lib/urls';import photos from '../content/team-photos.json';import {racePhotos} from '../content/race-photos';import {safeHref} from '../lib/navigation-links';import {useOriginalArticles} from '../api/newsroom-reader';import videoLibrary from '../content/newsroom-videos.json';import LiveNewsMedia from '../components/LiveNewsMedia.vue';
const {locale}=useI18n(),zh=computed(()=>locale.value==='zh-CN');const text=(cn:string,en:string)=>zh.value?cn:en;const feed=useNewsroom();
const filtersOpen=ref(false);
const tab=ref('news'),category=ref('all'),topic=ref(''),search=ref(''),language=ref('all'),publisher=ref(''),pageSize=ref(24),video=ref(videoLibrary[0]?.id||''),videoError=ref(false);const originals=useOriginalArticles();
const publishers=computed(()=>[...new Set(feed.data.value?.items.map(i=>i.publisher)||[])].sort());
const headline=(item:NewsIndexItem)=>zh.value?(item.titleZh||(item.language==='zh'?item.title:'中文标题翻译中，点击阅读新闻')):(item.titleEn||item.title);
const untranslated=computed(()=>results.value.filter(item=>item.language!=='zh'&&!item.titleZh).length);
const topics=computed(()=>feed.data.value?.topics.filter(t=>category.value==='all'||t.kind===category.value)||[]);
watch(category,()=>{topic.value='';pageSize.value=24;});watch([topic,search,language,publisher],()=>{pageSize.value=24;});
const results=computed(()=>{const now=Date.now();if(!feed.data.value?.expiresAt||Date.parse(feed.data.value.expiresAt)<now)return [];return feed.data.value.items.filter(item=>(category.value==='all'||item.categories.includes(category.value as 'driver'|'team'|'race'))&&(!topic.value||item.topics.includes(topic.value))&&(!publisher.value||item.publisher===publisher.value)&&(language.value==='all'||item.language==='zh'||!!item.titleZh)&&(!search.value||[item.title,item.titleZh||'',...item.topics.map(id=>feed.data.value?.topics.find(t=>t.id===id)?.nameZh||'')].some(title=>title.toLowerCase().includes(search.value.trim().toLowerCase())))).sort((a,b)=>Number(a.channel==='open-calendar')-Number(b.channel==='open-calendar'));});
const selectedTopic=computed(()=>feed.data.value?.topics.find(t=>t.id===topic.value));
const gallery=computed(()=>{const source=[...photos,...racePhotos.map(p=>({id:p.id,team:'Audi',title:p.alt,src:p.src,author:p.credit,license:'Non-commercial editorial use',licenseUrl:p.terms,source:p.source,captured:p.capturedAt}))].map(p=>({...p,imageHref:assetUrl(p.src)}));const all=[...source,...(feed.data.value?.photos?.items||[]).map(p=>({...p,imageHref:apiUrl(p.src)}))];const unique=[...new Map(all.map(p=>[p.source,p])).values()];const selected=selectedTopic.value;return unique.filter(p=>{if(!selected)return true;if(selected.kind==='team')return p.team===selected.name;if(selected.kind==='driver')return p.title.toLowerCase().includes(selected.name.split(' ').at(-1)!.toLowerCase());return p.title.toLowerCase().includes(selected.name.replace(' Grand Prix',' GP').toLowerCase());}).sort((a,b)=>b.captured.localeCompare(a.captured));});
async function selectTopic(id:string){filtersOpen.value=true;category.value='all';await nextTick();topic.value=id;}
const media=ref<HTMLVideoElement|null>(null);const chosen=computed(()=>videoLibrary.find(v=>v.id===video.value));
function releaseVideo(){if(media.value){media.value.pause();media.value.removeAttribute('src');media.value.load();}}
watch(video,()=>{media.value?.pause();videoError.value=false;});watch(tab,(next,previous)=>{if(previous==='videos'&&next!=='videos')releaseVideo();videoError.value=false;});onBeforeUnmount(releaseVideo);
const stamp=(value:string|null)=>value?new Date(value).toLocaleString(locale.value):text('等待首次同步','Awaiting first sync');
const healthy=computed(()=>feed.connected.value&&feed.data.value?.status==='ready');
</script>
<template><div class="page-heading newsroom-page-heading"><div><p class="eyebrow">NOBI / NEWSROOM</p><h1 tabindex="-1">{{text('F1 新闻专栏','F1 Newsroom')}}</h1><p class="muted">{{text('车手、车队与赛事动态，一处关注。','Drivers, teams and racing stories, together.')}}</p></div><RouterLink class="button" to="/news">{{text('赛事战报','Race briefs')}} ↗</RouterLink></div>
<section class="newsroom-status" aria-live="polite"><span class="newsroom-dot" :class="{online:healthy}"/><div><strong>{{feed.error.value?text('连接暂不可用，自动重试中','Connection unavailable; retrying'):healthy?text('正在接收新闻更新','Receiving news updates'):text('自动更新中','Automatic updates')}}</strong><p class="caption">{{text('已收录 ' ,'Collected ' )}}{{feed.data.value?.items.length||0}} {{text('条 · 发布者 ' ,'stories · Publishers ' )}}{{publishers.length}}</p><details class="caption"><summary>{{text('同步：','Synced: ')}}{{stamp(feed.data.value?.syncedAt||null)}}</summary><p>{{text('每 2 分钟检查新文章清单与多语种索引，补抓过去 24 小时遗漏的批次；另同步开放赛历。各通道独立重试，新条目推送到本页。索引发现时间不等于文章发布时间。','Article discovery and multilingual indexes are checked every 2 minutes, with missing batches recovered over 24 hours. An open calendar is synchronized separately. Channels retry independently; discovery time is not publication time.')}}</p><p>{{text('最近检查：','Last checked: ')}}{{stamp(feed.data.value?.checkedAt||null)}} · {{text('来源批次：','Source batch: ')}}{{stamp(feed.data.value?.datasetAt||null)}}</p><ul class="newsroom-channel-list"><li v-for="channel in feed.data.value?.channels" :key="channel.id"><strong>{{zh?channel.name:channel.nameEn||channel.name}}</strong> · {{channel.status==='ready'?text('正常','Ready'):text('延迟 / 重试中','Delayed / retrying')}}<br/>{{text('最近成功：','Last successful check: ')}}{{stamp(channel.syncedAt)}}</li></ul></details></div><button class="button" @click="feed.reload">{{text('刷新','Refresh')}}</button></section>
<p v-if="feed.data.value?.status==='delayed'||feed.data.value?.status==='unavailable'" class="notice" role="status">{{text('来源暂有延迟；可用内容保留来源时间，恢复后自动更新。','Source is delayed. Available content retains its source time and updates when service recovers.')}}</p>
<div class="newsroom-tabs" role="group" :aria-label="text('内容类型','Content type')"><button v-for="[key,cn,en] in [['news','新闻','News'],['photos','图片','Photos'],['videos','视频','Videos']]" :key="key" class="button" :aria-pressed="tab===key" @click="tab=key">{{text(cn!,en!)}}</button></div>
<details v-if="tab!=='videos'" class="newsroom-filter-panel" :open="filtersOpen" @toggle="filtersOpen=($event.target as HTMLDetailsElement).open"><summary>{{text('筛选与搜索','Filter and search')}} <span>{{results.length}} {{text('条线索','stories')}}</span></summary><div class="newsroom-filters"><label>{{text('分类','Category')}}<select v-model="category" :aria-label="text('分类','Category')"><option value="all">{{text('全部动态','All stories')}}</option><option value="driver">{{text('车手','Drivers')}}</option><option value="team">{{text('车队','Teams')}}</option><option value="race">{{text('赛事','Races')}}</option></select></label><label>{{text('关注对象','Subject')}}<select v-model="topic" :aria-label="text('关注对象','Subject')"><option value="">{{text('全部对象','All subjects')}}</option><option v-for="item in topics" :key="item.id" :value="item.id">{{zh?item.nameZh:item.name}}</option></select></label><template v-if="tab==='news'"><label>{{text('语言','Language')}}<select v-model="language" :aria-label="text('语言','Language')"><option value="zh">{{text('已有中文译题','Chinese titles ready')}}</option><option value="all">{{text('全部新闻（随界面语言翻译）','All news (translated to interface language)')}}</option></select></label><label>{{text('发布者','Publisher')}}<select v-model="publisher" :aria-label="text('发布者','Publisher')"><option value="">{{text('全部来源','All publishers')}}</option><option v-for="name in publishers" :key="name" :value="name">{{name}}</option></select></label><label class="newsroom-search-filter">{{text('搜索标题','Search headlines')}}<input v-model="search" :aria-label="text('搜索标题','Search headlines')" type="search" maxlength="100" :placeholder="text('输入车手、车队或赛事关键词','Driver, team or event')"/></label></template></div></details>
<template v-if="tab==='news'"><p v-if="zh&&untranslated" class="notice" role="status">{{untranslated}} 条新闻正在翻译；译文完成后自动更新，所有条目均可点击阅读。</p><h2>{{text('最新媒体动态','Latest media updates')}}</h2><p class="caption newsroom-rights">{{text('新闻索引：','News index: ')}}<a href="https://www.gdeltproject.org/" target="_blank" rel="noopener noreferrer">GDELT Project ↗</a> · <RouterLink to="/sources">{{text('来源与许可','Sources & licenses')}} ↗</RouterLink></p>
<div class="newsroom-grid"><article v-for="item in results.slice(0,pageSize)" :key="item.id" class="newsroom-card newsroom-index-card"><p class="eyebrow">{{item.publisher}} · {{item.channel==='open-calendar'?text('赛周预告','Calendar brief'):text('新闻线索','News discovery')}} · {{item.language==='zh'?text('中文','Chinese'):text('中文译文','Translated news')}}</p><h2><RouterLink :to="'/newsroom/'+item.id">{{headline(item)}} →</RouterLink></h2><details v-if="zh&&item.language!=='zh'"><summary>{{item.translation==='edited'?'本站中文整理 · 查看原题':item.titleZh?'机器译题 · 查看原题':'中文翻译排队中 · 查看原题'}}</summary><p :lang="item.originalLanguage||item.language">{{item.title}}</p><p v-if="item.translation==='machine'" class="caption">机器翻译，仅供参考，以原题和原文为准。</p></details><p class="caption">{{text('索引发现：','Indexed: ')}}{{stamp(item.indexedAt)}}</p><div class="newsroom-tags"><button v-for="id in item.topics.slice(0,4)" :key="id" @click="selectTopic(id)">{{zh?feed.data.value?.topics.find(t=>t.id===id)?.nameZh:feed.data.value?.topics.find(t=>t.id===id)?.name}}</button></div><RouterLink class="button" :to="'/newsroom/'+item.id">{{text('阅读新闻','Read news')}} →</RouterLink></article></div><p v-if="!results.length" class="empty-inline" role="status">{{feed.data.value?.status==='pending'?text('正在首次同步新闻索引，请稍后再看。','Synchronizing the first news index.'):text('当前筛选下暂无新闻；可切换“全部语种”或其他对象。','No stories match these filters. Try all languages or another subject.')}}</p><button v-if="results.length>pageSize" class="button" @click="pageSize+=24">{{text('加载更多','Load more')}}</button><section v-if="originals.length&&category==='all'&&!topic&&!search&&!publisher" class="newsroom-originals"><h2>{{text('站内双语报道','In-app bilingual reports')}}</h2><div class="newsroom-grid"><article v-for="item in originals.slice(0,2)" :key="item.id" class="newsroom-card"><p class="eyebrow">NOBI REPORT · {{text('站内正文','Full in-app report')}}</p><h2><RouterLink :to="'/newsroom/'+item.id">{{zh?item.titleZh:item.title}} →</RouterLink></h2><p>{{zh?item.paragraphsZh[0]:item.paragraphsEn[0]}}</p><RouterLink class="button" :to="'/newsroom/'+item.id">{{text('阅读全文','Read report')}} →</RouterLink></article></div></section></template>
<template v-if="tab==='photos'"><LiveNewsMedia :media="feed.data.value?.media" mode="photos"/><h2>{{text('历史图片资料库','Photo archive')}}</h2><p class="caption">{{text('自动相册最近同步：','Auto-gallery last sync: ')}}{{stamp(feed.data.value?.photos?.syncedAt||null)}} · {{text('每 30 分钟检查新上传的开放许可照片；另保留已核验的资料相册。','New openly licensed uploads checked every 30 minutes; the curated archive remains available.')}}</p><p class="caption">{{text('已核验许可的赛车照片资料库，按拍摄日期排序；照片独立署名，非新闻原站配图或实时画面。','Licensed racing photo library, sorted by capture date. Separately credited photographs, not publisher article imagery or live pictures.')}}</p><div class="newsroom-grid"><figure v-for="photo in gallery" :key="photo.id" class="newsroom-photo"><img :src="photo.imageHref" :alt="photo.title" width="1920" height="1280" loading="lazy"/><figcaption><strong>{{photo.team}}</strong><p>{{photo.captured}} · {{photo.author}}</p><a :href="safeHref(photo.source)" target="_blank" rel="noopener noreferrer">{{text('照片来源','Photo source')}} ↗</a> · <a :href="safeHref(photo.licenseUrl)" target="_blank" rel="noopener noreferrer">{{photo.license}} ↗</a></figcaption></figure></div><p v-if="!gallery.length" class="empty-inline">{{text('该对象暂无已核验图片，可查看全部图片。','No verified photos for this subject; try all photos.')}}</p></template>
<template v-if="tab==='videos'"><LiveNewsMedia :media="feed.data.value?.media" mode="videos"/><details class="newsroom-archive" @toggle="!($event.target as HTMLDetailsElement).open&&media?.pause()"><summary>{{text('历史实拍视频资料库','Archive footage library')}}</summary><section class="newsroom-video"><label>{{text('选择视频','Choose video')}}<select v-model="video" :aria-label="text('选择视频','Choose video')"><option v-for="source in videoLibrary" :key="source.id" :value="source.id">{{zh?source.titleZh:source.title}}</option></select></label><template v-if="chosen"><h2>{{zh?chosen.titleZh:chosen.title}}</h2><p class="caption">{{text('实拍资料视频 · 拍摄日期：','Archive footage · Captured: ')}}{{chosen.captured}} · {{chosen.author}}</p><p>{{text('视频由本站直接提供，点击播放后观看，不依赖 YouTube，也不跳转至外站。资料拍摄时间以图注为准，不是当前分站直播或最新比赛集锦。','Videos are served by NOBI and play here when you press Play, without YouTube or an external player page. Capture dates are explicit; this is archive footage, not a live race or current highlights.')}}</p><video ref="media" class="newsroom-native-video" controls playsinline preload="metadata" :src="assetUrl(chosen.src)" @error="videoError=true">{{text('浏览器暂不支持此视频格式。','This browser does not support this video format.')}}</video><p v-if="videoError" class="notice" role="alert">{{text('视频暂时加载失败，请检查网络后重试或选择另一段视频。','Video could not load. Check the connection and retry or select another clip.')}}<button class="button" @click="videoError=false;video=videoLibrary.find(v=>v.id!==video)?.id||video">{{text('切换视频','Try another clip')}}</button></p><p class="caption">{{text('格式转换：WebM 转为 H.264/AAC MP4，保留完整片段和署名；相同方式共享。','Format conversion: WebM to H.264/AAC MP4, retaining the complete clip and attribution; shared alike.')}}</p><details><summary>{{text('视频来源与许可（可选查看）','Video source and license (optional)')}}</summary><a :href="chosen.source" target="_blank" rel="noopener noreferrer">Wikimedia Commons ↗</a> · <a :href="chosen.licenseUrl" target="_blank" rel="noopener noreferrer">{{chosen.license}} ↗</a></details></template></section></details></template>
</template>
